import { parseJs, walk, collectBindings, propName, type AnyNode } from "./ast";
import type { FileMap, GeneratedTest } from "./types";
export { jsonShape } from "./testgen-shape";

export const TEST_DIR = "test/necro";
export const SNAPSHOT_DIR = "test/necro/__snapshots__";
export const SNAPSHOT_FILE = "test/necro/__snapshots__/routes.json";

const HEADER = (strategy: string) => `'use strict';
// Generated by RepoNecromancer — ${strategy}.
// These characterization tests run against BOTH the legacy and the resurrected
// tree, so a green "after" run proves behaviour survived the upgrade.
const test = require('node:test');
const assert = require('node:assert/strict');
const path = require('node:path');
const ROOT = path.join(__dirname, '..', '..');
`;

function q(s: string) {
  return JSON.stringify(s);
}

function isCodeFile(p: string) {
  return /\.(c?js)$/.test(p) && !/(^|\/)(node_modules|bower_components|dist|vendor|coverage|test|tests|spec|__tests__)\//.test(p) && !/\.min\.js$/.test(p) && !/(^|\/)(Gruntfile|gulpfile|eslint\.config)\.c?js$/.test(p) && !p.startsWith("necro-compat/");
}

export interface Entrypoints {
  servers: string[];
  clis: string[];
}

export function findEntrypoints(pkg: any, files: FileMap): Entrypoints {
  const servers = new Set<string>();
  const clis = new Set<string>();
  const start: string | undefined = pkg?.scripts?.start;
  const m = start?.match(/^node\s+([\w./-]+)/);
  if (m) servers.add(m[1].replace(/^\.\//, "").replace(/(\.js)?$/, ".js"));
  else if (!start && files["server.js"]) servers.add("server.js");
  const bin = pkg?.bin;
  if (typeof bin === "string") clis.add(bin.replace(/^\.\//, ""));
  else if (bin && typeof bin === "object") Object.values(bin).forEach((b: any) => clis.add(String(b).replace(/^\.\//, "")));
  return { servers: [...servers].filter((f) => files[f] !== undefined), clis: [...clis].filter((f) => files[f] !== undefined) };
}

interface Example {
  expr: string;
  expected: string | null;
  throws: boolean;
  roots: string[];
}

function parseExamples(code: string): Example[] {
  const out: Example[] = [];
  const blocks = code.match(/\/\*\*[\s\S]*?\*\//g) ?? [];
  for (const block of blocks) {
    const lines = block.split("\n").map((l) => l.replace(/^\s*\/?\*+\/?\s?/, "").trimEnd());
    let inExample = false;
    for (const line of lines) {
      if (/^@example\b/.test(line)) {
        inExample = true;
        const rest = line.replace(/^@example\s*/, "");
        if (rest) pushExample(rest, out);
        continue;
      }
      if (/^@\w+/.test(line)) inExample = false;
      else if (inExample && line.trim()) pushExample(line.trim(), out);
    }
  }
  return out;
}

function pushExample(line: string, out: Example[]) {
  const m = line.match(/^(.+?)\s*\/\/\s*(=>|throws)\s*(.*)$/);
  if (!m) return;
  const expr = m[1].replace(/;$/, "").trim();
  const throws = m[2] === "throws";
  const expected = throws ? null : m[3].trim();
  if (!parseJs(`(${expr});`) || (expected !== null && (!expected || !parseJs(`(${expected});`)))) return;
  const ast = parseJs(`(${expr});`);
  const roots = new Set<string>();
  if (ast) {
    walk(ast as AnyNode, (n) => {
      if (n.type === "CallExpression") {
        if (n.callee.type === "Identifier") roots.add(n.callee.name);
        else if (n.callee.type === "MemberExpression") {
          let o = n.callee.object;
          while (o.type === "MemberExpression") o = o.object;
          if (o.type === "Identifier") roots.add(o.name);
        }
      }
    });
  }
  if (!roots.size) return;
  out.push({ expr, expected, throws, roots: [...roots] });
}

/** Routes registered on an exported express app: [method, path]. */
function findRoutes(code: string): { app: string; routes: Array<[string, string]> } | null {
  const ast = parseJs(code);
  if (!ast) return null;
  const b = collectBindings(ast as AnyNode);
  if (!b.expressApps.size) return null;
  let exported: string | null = null;
  const routes: Array<[string, string]> = [];
  walk(ast as AnyNode, (n) => {
    if (n.type === "AssignmentExpression" && n.left.type === "MemberExpression" && n.left.object.type === "Identifier" && n.left.object.name === "module" && propName(n.left) === "exports" && n.right.type === "Identifier" && b.expressApps.has(n.right.name)) {
      exported = n.right.name;
    }
    if (n.type === "CallExpression" && n.callee.type === "MemberExpression" && n.callee.object.type === "Identifier" && b.expressApps.has(n.callee.object.name)) {
      const method = propName(n.callee);
      const p = n.arguments[0];
      if (method && ["get", "post", "put", "patch", "delete", "del"].includes(method) && p?.type === "StringLiteral" && p.value.startsWith("/")) {
        routes.push([method === "del" ? "DELETE" : method.toUpperCase(), p.value]);
      }
    }
  });
  if (!exported || !routes.length) return null;
  return { app: exported, routes };
}

function probePath(route: string) {
  return route
    .replace(/\{\/:(\w+)\}/g, "/necro-probe")
    .replace(/\{\*\w+\}|\*\w*/g, "necro-probe")
    .replace(/:(\w+)\??/g, "necro-probe");
}

export function generateTests(files: FileMap, pkg: any): GeneratedTest[] {
  const tests: GeneratedTest[] = [];
  const entry = findEntrypoints(pkg, files);
  const codeFiles = Object.keys(files).filter(isCodeFile).sort();
  const entrySet = new Set([...entry.servers, ...entry.clis]);

  // 1. JSDoc @example characterization
  {
    const parts: string[] = [];
    let cases = 0;
    let idx = 0;
    for (const f of codeFiles) {
      const exs = parseExamples(files[f]);
      if (!exs.length) continue;
      idx++;
      const body = exs
        .map((e) => {
          cases++;
          const name = `${f}: ${e.expr}${e.throws ? " throws" : ` => ${e.expected}`}`;
          const binds = e.roots.filter((r) => !(r in globalThis)).map((r) => `    const ${r} = pick(mod, ${q(r)});`).join("\n");
          const assertion = e.throws ? `assert.throws(() => ${e.expr});` : `assert.deepStrictEqual(${e.expr}, ${e.expected});`;
          return `  test(${q(name)}, () => {\n    const mod = require(path.join(ROOT, ${q(f)}));\n${binds}\n    ${assertion}\n  });`;
        })
        .join("\n");
      parts.push(`test.describe(${q(`@example contracts in ${f}`)}, () => {\n${body}\n});`);
    }
    if (cases) tests.push({ path: `${TEST_DIR}/examples.test.cjs`, strategy: "jsdoc-example", cases, content: HEADER("JSDoc @example contracts") + "const pick = (mod, name) => (typeof mod[name] === 'function' ? mod[name] : mod);\n\n" + parts.join("\n\n") + "\n" });
  }

  // 2. Module load smoke tests
  {
    const loadable = codeFiles.filter((f) => !entrySet.has(f) && !/^#!/.test(files[f]) && !/\.listen\(/.test(files[f]) && (!/\b(window|document)\b/.test(files[f]) || /typeof\s+module/.test(files[f])) && !/^\s*\(?function\s*\(\s*\$\s*\)/m.test(files[f]) && !/\bjQuery\b/.test(files[f]));
    if (loadable.length) {
      const body = loadable.map((f) => `test(${q(`module loads on modern Node: ${f}`)}, () => {\n  require(path.join(ROOT, ${q(f)}));\n});`).join("\n\n");
      tests.push({ path: `${TEST_DIR}/modules.test.cjs`, strategy: "module-load", cases: loadable.length, content: HEADER("module load smoke tests") + "\n" + body + "\n" });
    }
  }

  // 3. Express route smoke tests
  {
    const parts: string[] = [];
    let cases = 0;
    for (const f of codeFiles) {
      const r = findRoutes(files[f]);
      if (!r) continue;
      const seen = new Set<string>();
      const its = r.routes
        .filter(([m, p]) => !seen.has(m + p) && (seen.add(m + p), true))
        .map(([m, p]) => {
          cases++;
          const probe = probePath(p);
          // golden master only for parameterless GET routes
          const snap = m === "GET" && !p.includes(":") && !p.includes("{");
          const init = m === "GET" ? `{ method: 'GET' }` : `{ method: ${q(m)}, headers: { 'content-type': 'application/json' }, body: '{}' }`;
          return `  test(${q(`${m} ${p} never crashes with a 500${snap ? " and keeps its response shape" : ""}`)}, async () => {
    const res = await fetch(base + ${q(probe)}, ${init});
    const text = await res.text();
    assert.notEqual(res.status, 500, ${q(`${m} ${probe}`)} + ' returned 500: ' + text.slice(0, 200));${snap ? `
    goldenMaster(snapshot, ${q(`${m} ${p}`)}, res, text);` : ""}
  });`;
        })
        .join("\n\n");

      const snapshotPath = `path.join(ROOT, ${q(SNAPSHOT_FILE)})`;
      parts.push(`test.describe(${q(`HTTP routes in ${f}`)}, () => {
  let server;
  let base;
  let snapshot;
  test.before(async () => {
    const app = require(path.join(ROOT, ${q(f)}));
    server = app.listen(0);
    await new Promise((resolve, reject) => { server.once('listening', resolve); server.once('error', reject); });
    base = 'http://127.0.0.1:' + server.address().port;
    const fs = require('node:fs');
    const snap = ${snapshotPath};
    if (fs.existsSync(snap) && process.env.NECRO_RECORD !== '1') {
      try { snapshot = JSON.parse(fs.readFileSync(snap, 'utf8')); } catch { snapshot = null; }
    } else if (process.env.NECRO_RECORD === '1') {
      snapshot = fs.existsSync(snap) ? JSON.parse(fs.readFileSync(snap, 'utf8')) : {};
    }
  });
  test.after(() => {
    if (server) { server.close(); }
    if (process.env.NECRO_RECORD === '1' && snapshot) {
      const fs = require('node:fs');
      const dir = path.join(ROOT, ${q(SNAPSHOT_DIR)});
      if (!fs.existsSync(dir)) { fs.mkdirSync(dir, { recursive: true }); }
      fs.writeFileSync(${snapshotPath}, JSON.stringify(snapshot, null, 2) + '\\n');
    }
  });

${its}
});`);
    }
    if (cases) {
      const shapeHelper = `
function jsonShape(v) {
  if (v === null) { return 'null'; }
  if (Array.isArray(v)) { return v.length === 0 ? [] : [jsonShape(v[0])]; }
  if (typeof v === 'object') {
    const out = {};
    for (const k of Object.keys(v)) { out[k] = jsonShape(v[k]); }
    return out;
  }
  return typeof v;
}

// Golden master: NECRO_RECORD=1 records { status, contentType, shape } from the
// legacy tree; otherwise any recorded entry must match exactly.
function goldenMaster(snapshot, key, res, text) {
  if (!snapshot) { return; }
  const contentType = (res.headers.get('content-type') || '').split(';')[0].trim();
  let shape = 'text';
  if (/json/.test(contentType)) {
    try { shape = jsonShape(JSON.parse(text)); } catch { shape = 'text'; }
  }
  const observed = { status: res.status, contentType: contentType, shape: shape };
  if (process.env.NECRO_RECORD === '1') { snapshot[key] = observed; return; }
  if (snapshot[key]) {
    assert.deepStrictEqual(observed, snapshot[key], key + ' drifted from the legacy golden master');
  }
}
`;
      tests.push({ path: `${TEST_DIR}/routes.test.cjs`, strategy: "route-smoke", cases, content: HEADER("HTTP route smoke tests") + shapeHelper + "\n" + parts.join("\n\n") + "\n" });
    }
  }

  // 4. Entrypoint boot tests
  {
    const parts: string[] = [];
    for (const s of entry.servers) {
      parts.push(`test(${q(`server entrypoint boots and stays up: ${s}`)}, async () => {
  const { spawn } = require('node:child_process');
  const child = spawn(process.execPath, [path.join(ROOT, ${q(s)})], { cwd: ROOT, env: Object.assign({}, process.env, { PORT: '0', NODE_ENV: 'test' }) });
  let stderr = '';
  child.stderr.on('data', (d) => { stderr += d; });
  const exited = await new Promise((resolve) => {
    const t = setTimeout(() => resolve(null), 2500);
    child.once('exit', (code) => { clearTimeout(t); resolve({ code }); });
  });
  child.kill();
  assert.equal(exited, null, 'process exited early (code ' + (exited && exited.code) + '):\\n' + stderr.slice(0, 600));
});`);
    }
    for (const c of entry.clis) {
      parts.push(`test(${q(`CLI runs without crashing: ${c}`)}, () => {
  const { spawnSync } = require('node:child_process');
  const r = spawnSync(process.execPath, [path.join(ROOT, ${q(c)})], { cwd: ROOT, encoding: 'utf8', timeout: 10000 });
  const crashed = /\\n\\s+at .+:\\d+:\\d+/.test(r.stderr || '') || r.signal !== null;
  assert.ok(!crashed, 'CLI crashed:\\n' + String(r.stderr).slice(0, 600));
});`);
    }
    if (parts.length) tests.push({ path: `${TEST_DIR}/boot.test.cjs`, strategy: "entrypoint-boot", cases: parts.length, content: HEADER("entrypoint boot tests") + "\n" + parts.join("\n\n") + "\n" });
  }

  return tests;
}
